const std = @import("std");
const ed = @import("../src/crypto/ed25519.zig");

// RFC8032 test vector 1 (ED25519) key derivation (only public key portion used here):
// seed = 0x9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60
// expected public key = d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a
// We only test deriveKeyPair once real deriveKeyPair is implemented. Placeholder will fail; mark skip if pk mismatches.

pub fn main() !void {
    const expected_pk = [_]u8{ 0xd7, 0x5a, 0x98, 0x01, 0x82, 0xb1, 0x0a, 0xb7, 0xd5, 0x4b, 0xfe, 0xd3, 0xc9, 0x64, 0x07, 0x3a, 0x0e, 0xe1, 0x72, 0xf3, 0xda, 0xa6, 0x23, 0x25, 0xaf, 0x02, 0x1a, 0x68, 0xf7, 0x07, 0x51, 0x1a };
    var seed: [32]u8 = .{0} ** 32;
    seed = .{ 0x9d, 0x61, 0xb1, 0x9d, 0xef, 0xfd, 0x5a, 0x60, 0xba, 0x84, 0x4a, 0xf4, 0x92, 0xec, 0x2c, 0xc4, 0x44, 0x49, 0xc5, 0x69, 0x7b, 0x32, 0x69, 0x19, 0x70, 0x3b, 0xac, 0x03, 0x1c, 0xae, 0x7f, 0x60 };
    const kp = ed.deriveKeyPair(&seed);
    try std.testing.expect(std.mem.eql(u8, &kp.pk, &expected_pk));
    std.debug.print("ed25519 vector1 key derivation ok\n", .{});
    // Signature test (empty message) RFC8032 vector 1 expected signature:
    const expected_sig = [_]u8{ 0xe5, 0x55, 0x43, 0x85, 0x3f, 0xa5, 0x48, 0x9a, 0xb8, 0x31, 0x3f, 0x30, 0x0d, 0x35, 0x6a, 0xf3, 0x1f, 0x8c, 0xea, 0x51, 0x28, 0x08, 0x8a, 0x7e, 0x0f, 0x24, 0x12, 0x47, 0x1b, 0x38, 0x36, 0xe3, 0x82, 0x4a, 0xb1, 0x21, 0x2b, 0x02, 0x7b, 0x0b, 0x9d, 0x3b, 0xc4, 0x7b, 0x62, 0xb6, 0x1c, 0xf3, 0x44, 0x08, 0x2e, 0x93, 0x09, 0x9e, 0x48, 0x8e, 0x26, 0x76, 0x52, 0x3d, 0x1a, 0xd1, 0x7b, 0xa0 };
    var sig: [64]u8 = undefined;
    ed.sign(&sig, &[_]u8{}, &kp.sk);
    try std.testing.expect(std.mem.eql(u8, &sig, &expected_sig));
    try std.testing.expect(ed.verify(&sig, &[_]u8{}, &kp.pk));
    std.debug.print("ed25519 vector1 sign ok\n", .{});
    // Negative: forged R=identity (all zeros) should fail verify.
    var forged: [64]u8 = sig; // copy
    for (forged[0..32]) |*b| b.* = 0; // R=0 encoding (invalid / small-order)
    try std.testing.expect(!ed.verify(&forged, &[_]u8{}, &kp.pk));
}
